#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

size_t findLastShortBook(std::vector<Book> const& books) {
    // Store "index + 1" so that 0 cleanly means "not found".
    size_t best_plus_one = 0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(books.size());

    #pragma omp parallel for reduction(max:best_plus_one)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            const size_t candidate = static_cast<size_t>(i) + 1;
            if (candidate > best_plus_one) {
                best_plus_one = candidate;
            }
        }
    }

    // Return size_t(-1) if no short book exists.
    return (best_plus_one == 0) ? static_cast<size_t>(-1) : (best_plus_one - 1);
}
